import { defineConfig } from 'vite';

export default defineConfig({
  root: 'src',
  base: './',
  build: { outDir: '../docs', emptyOutDir: true },
  plugins: [{
    name: 'generated-folder-guides',
    generateBundle() {
      this.emitFile({ type: 'asset', fileName: '.nojekyll', source: '' });
      this.emitFile({ type: 'asset', fileName: 'README.md', source:
        '# Published website\n\nGenerated by `npm run build` from [src/](../src/README.md).\nServe this folder with GitHub Pages. Commit it for branch-folder publishing.\nDo not edit by hand; builds replace its contents. No source materials belong here.\n\n[Project guide](../README.md) · [Generated assets](assets/README.md)\n' });
      this.emitFile({ type: 'asset', fileName: 'assets/README.md', source:
        '# Generated assets\n\nHashed JavaScript and CSS generated by Vite with `npm run build`.\nThese files are committed with the website and replaced by each build.\nDo not edit them or place original source materials here.\n\n[Website guide](../README.md)\n' });
    },
  }],
});
